import { createEnvironment } from "@canonical/prism-core";
import { render, screen } from "@testing-library/react";
import { Suspense } from "react";
import { RelayEnvironmentProvider } from "react-relay";
import { describe, expect, it } from "vitest";
import createMetroFetch from "../../../../../../../testing/createMetroFetch.js";
import { ROLLING_STOCK_COUNT } from "../../../../../../../testing/fixtures.js";
import FleetCount from "./FleetCount.js";

/** Render the count over the metro graph, executed in process. */
const renderCount = (className?: string) =>
  render(
    <RelayEnvironmentProvider
      environment={createEnvironment({ fetchFn: createMetroFetch() })}
    >
      <Suspense fallback={null}>
        <FleetCount className={className} />
      </Suspense>
    </RelayEnvironmentProvider>,
  );

describe("FleetCount", () => {
  it("counts every rolling stock the index lists", async () => {
    renderCount();
    expect(await screen.findByRole("status")).toHaveTextContent(
      `${ROLLING_STOCK_COUNT} rolling stocks`,
    );
  });

  it("merges a consumer className after its own", async () => {
    renderCount("custom-class");
    const count = await screen.findByRole("status");
    expect(count.className).toContain("ds fleet-count");
    expect(count.className).toContain("custom-class");
    expect(count).toHaveAttribute("data-slot", "fleet-count");
  });
});
